  const q = new Uint16Array(u8.buffer), n = q.length / 3;
  const x = new Float64Array(n), y = new Float64Array(n), t = new Float64Array(n);
  for (let i = 0; i < n; i++){ x[i] = q[3 * i] / 65535 * MAN.W; y[i] = q[3 * i + 1] / 65535 * MAN.H; t[i] = q[3 * i + 2]; }
  return { n, x, y, t };
})();
